<?php
namespace App\Http\Controllers;
use App\Models\Project;
use App\Models\Workspace;
use App\Services\WorkspaceContext;
use App\Services\TeamAccess;
use App\Services\ProjectAccess as Access;
use App\Services\Identity;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Gate;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\ValidationException;
class ProjectController {
 public function __construct(private WorkspaceContext $context){}
 private function workspace(Request $r):Workspace{$w=$this->context->current($r);TeamAccess::role($w,$r->user());return $w;}
 private function allowed(Request $r,Project $p):Workspace{$w=$this->workspace($r);abort_unless((int)$p->workspace_id===(int)$w->id,404);Gate::authorize('view',$p);return $w;}
 private function q(Project $p,string $table){return DB::table($table)->where('project_id',$p->id);}
 private function row(Project $p,string $table,int $id){$x=$this->q($p,$table)->where('id',$id)->first();abort_unless($x,404);return $x;}
 private function fail(string $key,string $message):never{throw ValidationException::withMessages([$key=>$message]);}
 private function today(Request $r):string{return now()->setTimezone($r->user()->timezone?:'UTC')->toDateString();}
 private function insert(Project $p,string $table,array $data):int{return DB::table($table)->insertGetId($data+['project_id'=>$p->id,'created_at'=>now(),'updated_at'=>now()]);}
 private function change(Request $r,Project $p,string $ability,string $event,callable $fn){$w=$this->allowed($r,$p);DB::transaction(function()use($w,$r,$p,$ability,$event,$fn){$p=Access::lock($w,$r->user(),$p,$ability);$fn($p,$w);Access::audit($p,$r->user(),$event);});return back();}
 public function index(Request $r){$w=$this->workspace($r);$u=$r->user();$role=TeamAccess::role($w,$u);$projects=Access::visible($w,$u)->latest('id')->paginate(20);$templates=TeamAccess::staff($role)?DB::table('project_templates')->where('workspace_id',$w->id)->orderBy('name')->get():collect();$stats=Access::stats($w,$u);return view('projects.index',compact('projects','templates','stats','role'));}
 public function store(Request $r){
  $w=$this->workspace($r);$d=$r->validate(['name'=>'required|string|max:200','description'=>'nullable|string|max:10000','start_date'=>'required|date_format:Y-m-d|after_or_equal:2000-01-01','due_date'=>'required|date_format:Y-m-d|after_or_equal:start_date|before_or_equal:2100-12-31','currency'=>'required|in:BDT,USD','budget'=>'required|numeric|decimal:0,2|min:0|max:999999999999.99','template_id'=>'nullable|integer|min:1']);
  $p=DB::transaction(function()use($r,$w,$d){$role=TeamAccess::lock($w,$r->user());abort_unless(TeamAccess::staff($role),403);if(!TeamAccess::hr($role)&&$d['budget']!=0)abort(403);$template=null;if(!empty($d['template_id'])){$template=DB::table('project_templates')->where('workspace_id',$w->id)->where('id',$d['template_id'])->first();abort_unless($template,404);}unset($d['template_id']);$p=new Project($d);$p->workspace_id=$w->id;$p->creator_id=$r->user()->id;$p->status='active';$p->save();$p->members()->attach($r->user()->id,['role'=>'manager']);if($template)foreach(json_decode($template->tasks,true,512,JSON_THROW_ON_ERROR) as $title)$this->insert($p,'project_tasks',['title'=>$title,'start_date'=>$p->start_date->toDateString(),'due_date'=>$p->due_date->toDateString()]);Access::audit($p,$r->user(),'project_created');return $p;});return redirect()->route('projects.show',$p);
 }
 public function template(Request $r){$w=$this->workspace($r);$d=$r->validate(['name'=>'required|string|max:120','tasks'=>'required|string|max:10000']);$tasks=array_values(array_filter(array_map('trim',preg_split('/\R/u',$d['tasks']))));if(count($tasks)>50||!count($tasks)||collect($tasks)->contains(fn($t)=>mb_strlen($t)>200))$this->fail('tasks','Use 1–50 task titles, maximum 200 characters each.');DB::transaction(function()use($w,$r,$d,$tasks){abort_unless(TeamAccess::staff(TeamAccess::lock($w,$r->user())),403);$q=DB::table('project_templates')->where('workspace_id',$w->id)->where('name',$d['name']);if($q->exists())$this->fail('name','Template already exists.');DB::table('project_templates')->insert(['workspace_id'=>$w->id,'name'=>$d['name'],'tasks'=>json_encode($tasks,JSON_THROW_ON_ERROR),'created_at'=>now(),'updated_at'=>now()]);Identity::audit('project_template_created',$r->user(),$w);});return back();}
 public function show(Request $r,Project $project){
  $w=$this->allowed($r,$project);$p=$project;$manage=Gate::allows('manage',$p);$finance=Gate::allows('finance',$p);$editable=$p->status==='active';$members=$p->members()->get(['users.id','users.name'])->filter(fn($m)=>$w->roleFor($m)!==null)->values();$choices=$manage?$w->members()->get(['users.id','users.name'])->filter(fn($m)=>$w->roleFor($m)!==null)->values():collect();$tasks=$this->q($p,'project_tasks')->orderBy('due_date')->orderBy('id')->paginate(60,['*'],'tasks');$milestones=$this->q($p,'project_milestones')->orderBy('due_date')->paginate(20,['*'],'milestones');$comments=$this->q($p,'project_comments')->latest('id')->paginate(20,['*'],'comments');$approvals=DB::table('project_approvals')->whereIn('project_task_id',$this->q($p,'project_tasks')->select('id'))->latest('id')->paginate(20,['*'],'approvals');$attachments=$this->q($p,'project_attachments')->latest('id')->paginate(20,['id','user_id','name','size'],'attachments');$time=$this->q($p,'project_time_entries')->latest('local_date')->paginate(20,['*'],'time');$activity=$this->q($p,'project_activity')->latest('id')->paginate(20,['*'],'activity');$expenses=$finance?$this->q($p,'project_expenses')->latest('id')->paginate(20,['*'],'expenses'):null;$spent=$finance?$this->q($p,'project_expenses')->sum('amount'):null;$minutes=$this->q($p,'project_time_entries')->sum('minutes');$total=$this->q($p,'project_tasks')->count();$done=$this->q($p,'project_tasks')->where('status','completed')->count();$today=$this->today($r);$taskChoices=$this->q($p,'project_tasks')->orderBy('title')->limit(200)->get(['id','title']);$deps=DB::table('project_task_dependencies')->whereIn('task_id',$tasks->pluck('id'))->get()->groupBy('task_id');$names=$w->members()->pluck('users.name','users.id');return view('projects.show',compact('p','manage','finance','editable','members','choices','tasks','milestones','comments','approvals','attachments','time','activity','expenses','spent','minutes','total','done','today','taskChoices','deps','names'));
 }
 public function status(Request $r,Project $project){$d=$r->validate(['status'=>'required|in:active,completed,archived']);$w=$this->allowed($r,$project);DB::transaction(function()use($r,$w,$project,$d){TeamAccess::lock($w,$r->user());$p=Project::where('workspace_id',$w->id)->lockForUpdate()->findOrFail($project->id);Gate::authorize('manage',$p);if($d['status']==='completed'&&($this->q($p,'project_tasks')->where('status','!=','completed')->exists()||$this->q($p,'project_milestones')->whereNull('completed_at')->exists()))$this->fail('status','Finish all tasks and milestones first.');$p->update($d);Access::audit($p,$r->user(),'project_status_changed');});return back();}
 public function member(Request $r,Project $project){$d=$r->validate(['user_id'=>'required|integer|min:1','role'=>'required|in:manager,member,remove']);return $this->change($r,$project,'manage','project_members_changed',function($p,$w)use($r,$d){$target=TeamAccess::target($w,(int)$d['user_id']);$role=$w->roleFor($target);if($d['role']==='manager'&&!in_array($role,['owner','admin','manager'],true))$this->fail('role','Project manager requires workspace management role.');if(!TeamAccess::hr($w->roleFor($r->user()))){abort_unless($role==='member'&&$d['role']!=='manager',403);}if($d['role']==='remove'){if($this->q($p,'project_tasks')->where('assignee_id',$target->id)->where('status','!=','completed')->exists())$this->fail('user_id','Reassign open tasks before removing member.');$p->members()->detach($target->id);}else $p->members()->syncWithoutDetaching([$target->id=>['role'=>$d['role']]]);});}
 public function milestone(Request $r,Project $project){$d=$r->validate(['title'=>'required|string|max:200','due_date'=>'required|date_format:Y-m-d']);return $this->change($r,$project,'manage','project_milestone_created',function($p)use($d){if($d['due_date']<$p->start_date->toDateString()||$d['due_date']>$p->due_date->toDateString())$this->fail('due_date','Choose a date within the project.');$this->insert($p,'project_milestones',$d);});}
 public function completeMilestone(Request $r,Project $project,int $milestone){return $this->change($r,$project,'manage','project_milestone_completed',function($p)use($milestone){$this->row($p,'project_milestones',$milestone);if($this->q($p,'project_tasks')->where('milestone_id',$milestone)->where('status','!=','completed')->exists())$this->fail('milestone','Finish milestone tasks first.');$this->q($p,'project_milestones')->where('id',$milestone)->update(['completed_at'=>now(),'updated_at'=>now()]);});}
 public function task(Request $r,Project $project){$d=$r->validate(['title'=>'required|string|max:200','description'=>'nullable|string|max:10000','assignee_id'=>'nullable|integer|min:1','milestone_id'=>'nullable|integer|min:1','priority'=>'required|in:low,medium,high,urgent','start_date'=>'required|date_format:Y-m-d','due_date'=>'required|date_format:Y-m-d|after_or_equal:start_date','requires_approval'=>'required|boolean']);return $this->change($r,$project,'manage','project_task_created',function($p,$w)use($d){if($d['start_date']<$p->start_date->toDateString()||$d['due_date']>$p->due_date->toDateString())$this->fail('due_date','Task dates must be inside project dates.');if(!empty($d['assignee_id']))$this->assignee($p,$w,(int)$d['assignee_id']);if(!empty($d['milestone_id'])){$m=$this->row($p,'project_milestones',$d['milestone_id']);if($m->completed_at)$this->fail('milestone_id','Milestone completed.');}$this->insert($p,'project_tasks',$d);});}
 private function assignee(Project $p,Workspace $w,int $id):void{TeamAccess::target($w,$id);abort_unless($p->members()->where('users.id',$id)->whereIn('project_members.role',['manager','member'])->exists(),422,'Assignee must belong to project.');}
 public function assign(Request $r,Project $project,int $task){$d=$r->validate(['assignee_id'=>'nullable|integer|min:1','version'=>'required|integer|min:1']);return $this->change($r,$project,'manage','project_task_assigned',function($p,$w)use($d,$task){$t=$this->row($p,'project_tasks',$task);$this->version($t,$d);if(in_array($t->status,['review','completed'],true))$this->fail('assignee_id','Submitted or completed tasks cannot be reassigned.');if(!empty($d['assignee_id']))$this->assignee($p,$w,(int)$d['assignee_id']);$this->q($p,'project_tasks')->where('id',$task)->update(['assignee_id'=>$d['assignee_id']??null,'version'=>$t->version+1,'updated_at'=>now()]);});}
 private function version($t,array $d):void{if((int)$t->version!==(int)$d['version'])$this->fail('version','Task changed. Reload before saving.');}
 public function dependency(Request $r,Project $project,int $task){$d=$r->validate(['depends_on_id'=>'required|integer|min:1','remove'=>'nullable|boolean']);return $this->change($r,$project,'manage','project_dependency_changed',function($p)use($d,$task){$t=$this->row($p,'project_tasks',$task);$dep=$this->row($p,'project_tasks',$d['depends_on_id']);$q=DB::table('project_task_dependencies')->where('task_id',$task)->where('depends_on_id',$dep->id);if(in_array($t->status,['completed','review'],true))$this->fail('depends_on_id','Cannot change dependencies of completed or submitted task.');if(!empty($d['remove'])){$q->delete();return;}$graph=DB::table('project_task_dependencies')->whereIn('task_id',$this->q($p,'project_tasks')->select('id'))->get()->groupBy('task_id');$stack=[$dep->id];$seen=[];while($stack){$id=array_pop($stack);if((int)$id===$task)$this->fail('depends_on_id','Dependency cycle.');if(isset($seen[$id]))continue;$seen[$id]=true;foreach($graph->get($id,collect()) as $edge)$stack[]=$edge->depends_on_id;}if(!$q->exists())DB::table('project_task_dependencies')->insert(['task_id'=>$task,'depends_on_id'=>$dep->id]);});}
 private function ready(Project $p,int $task):void{if(DB::table('project_task_dependencies')->join('project_tasks','project_tasks.id','=','project_task_dependencies.depends_on_id')->where('task_id',$task)->where('project_tasks.project_id',$p->id)->where('project_tasks.status','!=','completed')->exists())$this->fail('status','Complete dependencies first.');}
 public function transition(Request $r,Project $project,int $task){$d=$r->validate(['status'=>'required|in:pending,in_progress,completed,review','version'=>'required|integer|min:1']);return $this->change($r,$project,'view','project_task_transition',function($p)use($r,$d,$task){$t=$this->row($p,'project_tasks',$task);$this->version($t,$d);abort_unless(Gate::allows('manage',$p)||(int)$t->assignee_id===(int)$r->user()->id,403);$status=$d['status'];if($t->status==='review')$this->fail('status','Pending approval must be decided first.');if($t->status==='completed')$this->fail('status','Completed tasks are immutable.');if(in_array($status,['completed','review'],true))$this->ready($p,$task);if($status==='completed'&&$t->requires_approval)$this->fail('status','Submit for approval.');if($status==='review'){if(!$t->requires_approval)$this->fail('status','Approval not required.');DB::table('project_approvals')->insert(['project_task_id'=>$task,'submitted_by'=>$r->user()->id,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);}$this->q($p,'project_tasks')->where('id',$task)->update(['status'=>$status,'version'=>$t->version+1,'updated_at'=>now()]);});}
 public function decide(Request $r,Project $project,int $approval){$d=$r->validate(['status'=>'required|in:approved,rejected','note'=>'nullable|string|max:3000']);return $this->change($r,$project,'manage','project_approval_decided',function($p)use($r,$d,$approval){$a=DB::table('project_approvals')->whereIn('project_task_id',$this->q($p,'project_tasks')->select('id'))->where('id',$approval)->first();abort_unless($a,404);$t=$this->row($p,'project_tasks',$a->project_task_id);abort_if((int)$a->submitted_by===(int)$r->user()->id||(int)$t->assignee_id===(int)$r->user()->id,403);if($a->status!=='pending'||$t->status!=='review')$this->fail('status','Approval already decided.');if($d['status']==='approved')$this->ready($p,$t->id);DB::table('project_approvals')->where('id',$approval)->update(['status'=>$d['status'],'note'=>$d['note']??null,'reviewer_id'=>$r->user()->id,'decided_at'=>now(),'updated_at'=>now()]);$this->q($p,'project_tasks')->where('id',$t->id)->update(['status'=>$d['status']==='approved'?'completed':'in_progress','version'=>$t->version+1,'updated_at'=>now()]);});}
 public function comment(Request $r,Project $project){$d=$r->validate(['body'=>'required|string|max:10000']);return $this->change($r,$project,'view','project_comment_created',fn($p)=>$this->insert($p,'project_comments',$d+['user_id'=>$r->user()->id]));}
 public function expense(Request $r,Project $project){$d=$r->validate(['title'=>'required|string|max:200','amount'=>'required|numeric|decimal:0,2|min:0.01|max:999999999999.99','local_date'=>'required|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:'.$this->today($r)]);return $this->change($r,$project,'finance','project_expense_logged',fn($p)=>$this->insert($p,'project_expenses',$d+['user_id'=>$r->user()->id]));}
 public function time(Request $r,Project $project){$d=$r->validate(['project_task_id'=>'nullable|integer|min:1','local_date'=>'required|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:'.$this->today($r),'minutes'=>'required|integer|min:1|max:1440','description'=>'required|string|max:200']);return $this->change($r,$project,'view','project_time_logged',function($p,$w)use($r,$d){if(!empty($d['project_task_id'])){$t=$this->row($p,'project_tasks',$d['project_task_id']);abort_unless(Gate::allows('manage',$p)||(int)$t->assignee_id===(int)$r->user()->id,403);}if(DB::table('project_time_entries')->whereIn('project_id',Project::where('workspace_id',$w->id)->select('id'))->where('user_id',$r->user()->id)->where('local_date',$d['local_date'])->sum('minutes')+$d['minutes']>1440)$this->fail('minutes','Daily project time exceeds 24 hours in this workspace.');$this->insert($p,'project_time_entries',$d+['user_id'=>$r->user()->id]);});}
 public function upload(Request $r,Project $project){$this->allowed($r,$project);$d=$r->validate(['file'=>'required|file|max:5120|mimes:pdf,png,jpg,jpeg,txt|extensions:pdf,png,jpg,jpeg,txt']);$file=$d['file'];$path=$file->store('project-files/'.$project->id,'local');abort_unless($path,503);try{return $this->change($r,$project,'view','project_attachment_uploaded',function($p)use($r,$file,$path){abort_if($this->q($p,'project_attachments')->count()>=100,422);$name=mb_substr(preg_replace('/[\x00-\x1f\x7f]/u','',basename(str_replace('\\','/',$file->getClientOriginalName())))?:'file',0,200);$this->insert($p,'project_attachments',['user_id'=>$r->user()->id,'path'=>$path,'name'=>$name,'size'=>$file->getSize()]);});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}}
 public function download(Request $r,Project $project,int $attachment){$this->allowed($r,$project);$a=$this->row($project,'project_attachments',$attachment);abort_unless(Storage::disk('local')->exists($a->path),404);return Storage::disk('local')->download($a->path,$a->name,['Content-Type'=>'application/octet-stream','X-Content-Type-Options'=>'nosniff']);}
 public function deleteAttachment(Request $r,Project $project,int $attachment){return $this->change($r,$project,'view','project_attachment_removed',function($p)use($r,$attachment){$a=$this->row($p,'project_attachments',$attachment);abort_unless(Gate::allows('manage',$p)||(int)$a->user_id===(int)$r->user()->id,403);abort_unless(Storage::disk('local')->delete($a->path),503);$this->q($p,'project_attachments')->where('id',$attachment)->delete();});}
}
